const FALLBACK_CACHE='gigroup-offline-v1';
self.addEventListener('install',event=>{event.waitUntil((async()=>{try{const response=await fetch('/offline.html',{credentials:'same-origin',cache:'reload',redirect:'error'});if(response.ok&&response.headers.get('content-type')?.includes('text/html')){const cache=await caches.open(FALLBACK_CACHE);await cache.put('/offline.html',response)}}catch{}await self.skipWaiting()})())});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{for(const name of await caches.keys())if(name.startsWith('gigroup-offline-')&&name!==FALLBACK_CACHE)await caches.delete(name);await self.clients.claim()})())});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(url.origin!==self.location.origin||event.request.method!=='GET'||event.request.mode!=='navigate')return;event.respondWith((async()=>{try{return await fetch(event.request)}catch{const offline=await caches.match('/offline.html');return offline||new Response('GIGROUP is offline. Reconnect to open your CRM.',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}})}})())});
